local FILENAME = "VichianHUB_Key_Logs.txt"

Config = {
    api = "e46796c8-5d28-4932-adc1-8ec5018efbf3",
    service = "VichianHUB",
    provider = "VichianHUB"
}

local isValid = false
local savedkey = isfile(FILENAME) and readfile(FILENAME) or nil
local keyinput = ""

local function checkKey(userKey)
    local ok, result = pcall(function()
        local JunkieKeySystem = loadstring(game:HttpGet("https://junkie-development.de/sdk/JunkieKeySystem.lua"))()
        return JunkieKeySystem.verifyKey(Config.api, userKey, Config.service)
    end)
    if not ok then
        return false
    end
    return result == true
end


local function onCheckButton()
    local keyinput = savedkey or KeyInput.Text
    if keyinput == "" then
        createNotification("please input your key!", "error", 3)
        return
    end

    local res = checkKey(keyinput)
	if not res then
		createNotification("Key is Invalid", "error", 3)
	else
		createNotification("Key is Valid!", "success", 3)
		writefile("VichianHUB_Key_Logs.txt", keyinput)
		isValid = true
		KeySystemGUI:Destroy()
	end
end

CheckKeyButton.MouseButton1Click:Connect(onCheckButton)

