	-- UIGradient_5.Color = ColorSequence.new{ColorSequenceKeypoint.new(0.00, Color3.fromRGB(21, 121, 3)), ColorSequenceKeypoint.new(1.00, Color3.fromRGB(151, 255, 119))}
	-- UIGradient_4.Color = ColorSequence.new{ColorSequenceKeypoint.new(0.00, Color3.fromRGB(97, 97, 97)), ColorSequenceKeypoint.new(1.00, Color3.fromRGB(171, 171, 171))}
end)

_24HR.MouseButton1Click:Connect(function()
	KeyPreset = '24'
	StatusKey.BackgroundColor3 = Color3.fromRGB(0, 255, 0)
	StatusKey_2.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	-- UIGradient_4.Color = ColorSequence.new{ColorSequenceKeypoint.new(0.00, Color3.fromRGB(21, 121, 3)), ColorSequenceKeypoint.new(1.00, Color3.fromRGB(151, 255, 119))}
	-- UIGradient_5.Color = ColorSequence.new{ColorSequenceKeypoint.new(0.00, Color3.fromRGB(97, 97, 97)), ColorSequenceKeypoint.new(1.00, Color3.fromRGB(171, 171, 171))}
