GetKeyButton_2.MouseButton1Click:Connect(function()
	if KeyPreset == '12' then
		local ok, res = pcall(function()
			local JunkieKeySystem = loadstring(game:HttpGet("https://junkie-development.de/sdk/JunkieKeySystem.lua"))()
			return JunkieKeySystem.getLink(Config.api, 'VichianHUB12HR', Config.service)
		end)

		if ok and res then
			if setclipboard then
				setclipboard(res)
			end
			createNotification("Copy Link To Clipboard For 12hr Key", "success", 3)
			createNotification("Reset Script For Update Key In System", "success", 3)
			KeySystemGUI:Destroy()
		else
			createNotification("Failed", "error", 3)
		end
	elseif KeyPreset == '24' then
		local ok, res = pcall(function()
			local JunkieKeySystem = loadstring(game:HttpGet("https://junkie-development.de/sdk/JunkieKeySystem.lua"))()
			return JunkieKeySystem.getLink(Config.api, 'VichianHUB24HR', Config.service)
		end)

		if ok and res then
			if setclipboard then
				setclipboard(res)
			end
			createNotification("Copy Link To Clipboard For 24hr Key", "success", 3)
			createNotification("Reset Script For Update Key In System", "success", 3)
			KeySystemGUI:Destroy()
		else
			createNotification("Failed", "error", 3)
		end
	else
		createNotification("Plese Select Key Duration", "", 3)
		return
	end
end)

if savedkey then
    createNotification("Checking Saved Key...", "", 2)
    if checkKey(savedkey) then
		createNotification("Key is valid", "success", 3)
		isValid = true
		KeySystemGUI:Destroy()
	else
		createNotification("Key is invalid", "error", 3)
		delfile("VichianHUB_Key_Logs.txt")
	end
end

Close.MouseButton1Click:Connect(function()
	KeySystemGUI:Destroy()
end)

Discord.MouseButton1Click:Connect(function()
	createNotification("Discord On Maintenance", "error", 3)
end)

repeat task.wait() until isValid

local ALLOWED_GAME_ID = {
    [1] = 7862121304,
    [2] = 1235188606,
    [3] = 7471000866,
    [4] = 7798947148,
	[5] = 7394964165,
}

local found = false

for index, gameId in ipairs(ALLOWED_GAME_ID) do
    if game.GameId == gameId then
        found = true
        if index == 1 then
            loadstring(game:HttpGet('https://raw.githubusercontent.com/VichianCreater/RobloxScript/main/immortal_cultivation.lua'))()
        elseif index == 2 then
            loadstring(game:HttpGet('https://raw.githubusercontent.com/VichianCreater/RobloxScript/main/main.lua'))()
		elseif index == 3 then
            loadstring(game:HttpGet('https://raw.githubusercontent.com/VichianCreater/RobloxScript/main/anime_evolution.lua'))()
		elseif index == 4 then
            loadstring(game:HttpGet('https://raw.githubusercontent.com/VichianCreater/RobloxScript/main/Anime_Final_Quest.lua'))()
		elseif index == 5 then
            loadstring(game:HttpGet('https://raw.githubusercontent.com/VichianCreater/RobloxScript/main/Solo_hunter.lua'))()
        end

        break
    end
end

if not found then
    Fluent:Notify({
        Title = "Alert",
        Content = "The script does not support this game",
        Duration = 8
    })
    return
end

